  5132	                     * nested inside a tight list item, is wrapped with
  5133	                     * <p>...</p>. */
  5134	                    ctx->containers[ctx->n_containers].is_loose = TRUE;
  5135	                    ctx->n_containers++;
  5136	                }
  5137	            }
